CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260930160638_InitialCreate') THEN
    CREATE TABLE "Categories" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Name" text NOT NULL,
        "Description" text NOT NULL,
        CONSTRAINT "PK_Categories" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260930160638_InitialCreate') THEN
    CREATE TABLE "Requests" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Title" text NOT NULL,
        "Description" text NOT NULL,
        "CategoryId" integer NOT NULL,
        "State" integer NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL,
        "RequesterId" text NOT NULL,
        "AssigneeId" text,
        CONSTRAINT "PK_Requests" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Requests_Categories_CategoryId" FOREIGN KEY ("CategoryId") REFERENCES "Categories" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260930160638_InitialCreate') THEN
    CREATE TABLE "Comments" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "RequestId" integer NOT NULL,
        "Text" text NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL,
        "CreatedBy" text NOT NULL,
        "IsInternal" boolean NOT NULL,
        CONSTRAINT "PK_Comments" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Comments_Requests_RequestId" FOREIGN KEY ("RequestId") REFERENCES "Requests" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260930160638_InitialCreate') THEN
    CREATE TABLE "StatusHistories" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "RequestId" integer NOT NULL,
        "PreviousState" integer NOT NULL,
        "NewState" integer NOT NULL,
        "ChangedAt" timestamp with time zone NOT NULL,
        "ChangedBy" text NOT NULL,
        "Reason" text,
        CONSTRAINT "PK_StatusHistories" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_StatusHistories_Requests_RequestId" FOREIGN KEY ("RequestId") REFERENCES "Requests" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260930160638_InitialCreate') THEN
    INSERT INTO "Categories" ("Id", "Description", "Name")
    VALUES (1, 'Roads, bridges, etc.', 'Infrastructure');
    INSERT INTO "Categories" ("Id", "Description", "Name")
    VALUES (2, 'Water, electricity, etc.', 'Utilities');
    INSERT INTO "Categories" ("Id", "Description", "Name")
    VALUES (3, 'Public parks and recreation', 'Parks');
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260930160638_InitialCreate') THEN
    CREATE INDEX "IX_Comments_RequestId" ON "Comments" ("RequestId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260930160638_InitialCreate') THEN
    CREATE INDEX "IX_Requests_CategoryId" ON "Requests" ("CategoryId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260930160638_InitialCreate') THEN
    CREATE INDEX "IX_StatusHistories_RequestId" ON "StatusHistories" ("RequestId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260930160638_InitialCreate') THEN
    PERFORM setval(
        pg_get_serial_sequence('"Categories"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "Categories") + 1,
            nextval(pg_get_serial_sequence('"Categories"', 'Id'))),
        false);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260930160638_InitialCreate') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20260930160638_InitialCreate', '10.0.12');
    END IF;
END $EF$;
COMMIT;

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261014131923_M3P3_AuditLog_And_QueryIndexes') THEN
    CREATE TABLE "AuditLogs" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Actor" text NOT NULL,
        "Action" text NOT NULL,
        "EntityType" text NOT NULL,
        "EntityId" integer NOT NULL,
        "BeforeSummary" text,
        "AfterSummary" text,
        "Timestamp" timestamp with time zone NOT NULL,
        "CorrelationId" text,
        CONSTRAINT "PK_AuditLogs" PRIMARY KEY ("Id")
